 79	func succeeded(t *testing.T, s *Service, minor int64) Payment {
 80		t.Helper()
 81		ctx := context.Background()
 82		p, err := s.Create(ctx, CreateInput{MerchantID: "m_1", Amount: money.MustNew(minor, "USD")})
 83		if err != nil {
 84			t.Fatal(err)
 85		}
 86		if _, err := s.Authorize(ctx, p.ID); err != nil {
 87			t.Fatal(err)
 88		}
 89		p, err = s.Capture(ctx, p.ID)
 90		if err != nil {
 91			t.Fatal(err)
 92		}
 93		return p
 94	}
