139		ctx := context.Background()
140		tests := []struct {
141			name string
142			op   func(s *Service, id string) error
143			prep func(t *testing.T, s *Service) string
144		}{
145			{
146				name: "capture created",
147				prep: func(t *testing.T, s *Service) string {
148					p, _ := s.Create(ctx, CreateInput{MerchantID: "m", Amount: money.MustNew(100, "USD")})
149					return p.ID
150				},
151				op: func(s *Service, id string) error { _, err := s.Capture(ctx, id); return err },
152			},
153			{
154				name: "authorize succeeded",
155				prep: func(t *testing.T, s *Service) string { return succeeded(t, s, 100).ID },
156				op:   func(s *Service, id string) error { _, err := s.Authorize(ctx, id); return err },
157			},
158			{
159				name: "decline succeeded",
160				prep: func(t *testing.T, s *Service) string { return succeeded(t, s, 100).ID },
161				op:   func(s *Service, id string) error { _, err := s.Decline(ctx, id, "late"); return err },
162			},
163			{
164				name: "refund pending",
165				prep: func(t *testing.T, s *Service) string {
166					p, _ := s.Create(ctx, CreateInput{MerchantID: "m", Amount: money.MustNew(100, "USD")})
167					_, _ = s.Authorize(ctx, p.ID)
168					return p.ID
169				},
170				op: func(s *Service, id string) error {
171					_, _, err := s.Refund(ctx, id, money.MustNew(10, "USD"))
172					return err
173				},
174			},
175		}
176		for _, tt := range tests {
177			t.Run(tt.name, func(t *testing.T) {
178				s, _ := newTestService()
179				id := tt.prep(t, s)
180				if err := tt.op(s, id); !errors.Is(err, ErrInvalidTransition) {
181					t.Fatalf("error = %v, want ErrInvalidTransition", err)
