 67	func (s *Server) refundPayment(w http.ResponseWriter, r *http.Request) {
 68		id := r.PathValue("id")
 69		var req refundRequest
 70		if err := decodeJSON(r, &req); err != nil {
 71			writeError(w, err)
 72			return
 73		}
 74		p, err := s.svc.Get(r.Context(), id)
 75		if err != nil {
 76			writeError(w, err)
 77			return
 78		}
