func TestMemoryDoesNotShareMutableState(t *testing.T) {
	ctx := context.Background()
	m := NewMemory()

	refunds := make([]payment.Refund, 1, 4)
	refunds[0] = payment.Refund{ID: "ref_1", Amount: money.MustNew(10, "USD")}
	in := payment.Payment{
		ID:         "pay_1",
		MerchantID: "m1",
		Amount:     money.MustNew(100, "USD"),
		Refunded:   10,
		Status:     payment.StatusSucceeded,
		Refunds:    refunds,
		Version:    1,
	}
	if err := m.Create(ctx, in); err != nil {
		t.Fatal(err)
	}
	// Mutate caller's slice after Create (both existing element and spare capacity).
	in.Refunds[0].ID = "mutated_after_create"
	_ = append(in.Refunds, payment.Refund{ID: "phantom_create", Amount: money.MustNew(20, "USD")})

	got, err := m.Get(ctx, "pay_1")
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Refunds) != 1 || got.Refunds[0].ID != "ref_1" {
		t.Fatalf("after Create mutation: got %+v", got.Refunds)
	}

	// Mutate slice returned by Get.
	got.Refunds[0].ID = "mutated_after_get"
	got2, err := m.Get(ctx, "pay_1")
	if err != nil {
		t.Fatal(err)
	}
	if got2.Refunds[0].ID != "ref_1" {
		t.Fatalf("after Get mutation: got %+v", got2.Refunds)
	}

	// Update with a slice that has spare capacity, then mutate caller's slice.
	updSlice := make([]payment.Refund, 2, 6)
	updSlice[0] = got2.Refunds[0]
	updSlice[1] = payment.Refund{ID: "ref_2", Amount: money.MustNew(15, "USD")}
	got2.Refunded = 25
	got2.Refunds = updSlice
	if err := m.Update(ctx, got2); err != nil {
		t.Fatal(err)
	}
	updSlice[0].ID = "mutated_after_update"
	updSlice[1].ID = "mutated_after_update_2"
	_ = append(updSlice, payment.Refund{ID: "phantom_update", Amount: money.MustNew(30, "USD")})

	// Mutate slice returned by ListByMerchant.
	listed, _, err := m.ListByMerchant(ctx, "m1", payment.Page{Limit: 10})
	if err != nil {
		t.Fatal(err)
	}
	if len(listed) != 1 || len(listed[0].Refunds) != 2 || listed[0].Refunds[0].ID != "ref_1" || listed[0].Refunds[1].ID != "ref_2" {
		t.Fatalf("ListByMerchant got %+v", listed)
	}
	listed[0].Refunds[0].ID = "mutated_after_list"

	final, err := m.Get(ctx, "pay_1")
	if err != nil {
		t.Fatal(err)
	}
	if len(final.Refunds) != 2 || final.Refunds[0].ID != "ref_1" || final.Refunds[1].ID != "ref_2" {
		t.Fatalf("final stored refunds corrupted: %+v", final.Refunds)
	}
}

func TestConcurrentRefundsNoRaceOrPhantomRefunds(t *testing.T) {
	ctx := context.Background()
	repo := NewMemory()
	clk := clock.NewFake(time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC))
	svc := payment.NewService(repo, clk, payment.NewSeqIDs(), nil, payment.Config{FeeBps: 290})

	p, err := svc.Create(ctx, payment.CreateInput{MerchantID: "m_1", Amount: money.MustNew(10000, "USD")})
	if err != nil {
		t.Fatal(err)
	}
	if _, err := svc.Authorize(ctx, p.ID); err != nil {
		t.Fatal(err)
	}
	if _, err := svc.Capture(ctx, p.ID); err != nil {
		t.Fatal(err)
	}

	var (
		mu       sync.Mutex
		returned = make(map[string]int64)
	)

	// Run 8 waves of concurrent refunds with distinct amounts; in each wave
	// exactly one goroutine wins the optimistic lock and the rest fail with
	// ErrVersionConflict without leaving any trace in the stored payment.
	for wave := 0; wave < 8; wave++ {
		const workers = 12
		start := make(chan struct{})
		var wg sync.WaitGroup
		var wins int
		var conflicts int

		for w := 0; w < workers; w++ {
			amt := money.MustNew(int64(10+wave*20+w), "USD")
			wg.Add(1)
			go func(amount money.Amount) {
				defer wg.Done()
				<-start
				_, ref, err := svc.Refund(ctx, p.ID, amount)
				mu.Lock()
				defer mu.Unlock()
				switch {
				case err == nil:
					wins++
					returned[ref.ID] = ref.Amount.Minor
				case errors.Is(err, payment.ErrVersionConflict):
					conflicts++
				default:
					t.Errorf("unexpected error: %v", err)
				}
			}(amt)
		}

		// Also run concurrent readers (Get and List) during the wave.
		wg.Add(2)
		go func() {
			defer wg.Done()
			<-start
			got, err := svc.Get(ctx, p.ID)
			if err != nil {
				t.Errorf("Get: %v", err)
				return
			}
			var sum int64
			for _, r := range got.Refunds {
				sum += r.Amount.Minor
			}
			if sum != got.Refunded {
				t.Errorf("inconsistent snapshot: sum(refunds)=%d != refunded=%d", sum, got.Refunded)
			}
		}()
		go func() {
			defer wg.Done()
			<-start
			ps, _, err := svc.List(ctx, "m_1", payment.Page{Limit: 10})
			if err != nil || len(ps) != 1 {
				t.Errorf("List: %v len=%d", err, len(ps))
			}
		}()

		close(start)
		wg.Wait()

		if wins != 1 || conflicts != workers-1 {
			t.Fatalf("wave %d: wins=%d conflicts=%d", wave, wins, conflicts)
		}
	}

	got, err := svc.Get(ctx, p.ID)
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Refunds) != len(returned) {
		t.Fatalf("stored refunds len=%d, returned len=%d", len(got.Refunds), len(returned))
	}
	var sum int64
	for _, r := range got.Refunds {
		wantMinor, ok := returned[r.ID]
		if !ok {
			t.Fatalf("phantom refund %s in stored payment (never returned to client)", r.ID)
		}
		if r.Amount.Minor != wantMinor {
			t.Fatalf("refund %s amount=%d, want %d", r.ID, r.Amount.Minor, wantMinor)
		}
		sum += r.Amount.Minor
	}
	if sum != got.Refunded {
		t.Fatalf("sum of refunds %d != Refunded %d", sum, got.Refunded)
	}
}

