		t.Fatalf("after Get mutation: got %+v", got2.Refunds)
	}

	// Update with a slice that has spare capacity, then mutate caller's slice.
	updSlice := make([]payment.Refund, 2, 6)
	updSlice[0] = got2.Refunds[0]
	updSlice[1] = payment.Refund{ID: "ref_2", Amount: money.MustNew(15, "USD")}
	got2.Refunded = 25
	got2.Refunds = updSlice
	if err := m.Update(ctx, got2); err != nil {
		t.Fatal(err)
	}
	updSlice[0].ID = "mutated_after_update"
	updSlice[1].ID = "mutated_after_update_2"
	_ = append(updSlice, payment.Refund{ID: "phantom_update", Amount: money.MustNew(30, "USD")})

	// Mutate slice returned by ListByMerchant.
	listed, _, err := m.ListByMerchant(ctx, "m1", payment.Page{Limit: 10})
	if err != nil {
		t.Fatal(err)
	}
	if len(listed) != 1 || len(listed[0].Refunds) != 2 || listed[0].Refunds[0].ID != "ref_1" || listed[0].Refunds[1].ID != "ref_2" {
		t.Fatalf("ListByMerchant got %+v", listed)
	}
	listed[0].Refunds[0].ID = "mutated_after_list"

	final, err := m.Get(ctx, "pay_1")
	if err != nil {
		t.Fatal(err)
	}
	if len(final.Refunds) != 2 || final.Refunds[0].ID != "ref_1" || final.Refunds[1].ID != "ref_2" {
		t.Fatalf("final stored refunds corrupted: %+v", final.Refunds)
	}
