func TestPaymentCloneIsolation(t *testing.T) {
	orig := Payment{
		ID:         "pay_1",
		MerchantID: "m_1",
		Amount:     money.MustNew(500, "USD"),
		Refunded:   100,
		Status:     StatusSucceeded,
		Refunds:    make([]Refund, 1, 4),
		Version:    2,
	}
	orig.Refunds[0] = Refund{ID: "ref_1", Amount: money.MustNew(100, "USD")}

	cloned := orig.Clone()
	orig.Refunds[0].ID = "changed"
	orig.Refunds = append(orig.Refunds, Refund{ID: "ref_2", Amount: money.MustNew(50, "USD")})

	if len(cloned.Refunds) != 1 || cloned.Refunds[0].ID != "ref_1" {
		t.Fatalf("clone affected by mutation of original: %+v", cloned.Refunds)
	}

	emptyNonNil := Payment{ID: "pay_2", Refunds: make([]Refund, 0, 4)}
	emptyClone := emptyNonNil.Clone()
	if emptyClone.Refunds == nil || len(emptyClone.Refunds) != 0 {
		t.Fatalf("empty non-nil Refunds clone = %#v", emptyClone.Refunds)
	}
	_ = append(emptyNonNil.Refunds, Refund{ID: "ref_x"})
	if len(emptyClone.Refunds) != 0 {
		t.Fatalf("empty clone affected by append: %+v", emptyClone.Refunds)
	}

	nilRefunds := Payment{ID: "pay_3"}
	if nilRefunds.Clone().Refunds != nil {
		t.Fatalf("nil Refunds clone should stay nil")
	}
}

