	clk := clock.NewFake(time.Date(2026, 3, 1, 12, 0, 0, 0, time.UTC))
	svc := payment.NewService(repo, clk, payment.NewSeqIDs(), nil, payment.Config{FeeBps: 290})

	p, err := svc.Create(ctx, payment.CreateInput{MerchantID: "m_1", Amount: money.MustNew(10000, "USD")})
	if err != nil {
		t.Fatal(err)
	}
	_, _ = svc.Authorize(ctx, p.ID)
	_, _ = svc.Capture(ctx, p.ID)

	// Perform 3 sequential refunds first (len=3, where naive append had cap=4).
	var expectedSum int64
	returned := make(map[string]int64)
	for i := 0; i < 3; i++ {
		amt := money.MustNew(int64(100+i*10), "USD")
		_, ref, err := svc.Refund(ctx, p.ID, amt)
		if err != nil {
			t.Fatal(err)
		}
		returned[ref.ID] = ref.Amount.Minor
		expectedSum += ref.Amount.Minor
	}

	// Synchronize 8 concurrent refunds right after Get so all read the exact same version.
	const workers = 8
	var ready sync.WaitGroup
	ready.Add(workers)
	release := make(chan struct{})
	repo.onGet = func() {
		ready.Done()
		<-release
	}

	var (
		mu        sync.Mutex
		wins      int
		conflicts int
		done      sync.WaitGroup
	)
	for w := 0; w < workers; w++ {
		amt := money.MustNew(int64(1+w*7), "USD")
		done.Add(1)
		go func(amount money.Amount) {
			defer done.Done()
			_, ref, err := svc.Refund(ctx, p.ID, amount)
			mu.Lock()
			defer mu.Unlock()
			switch {
			case err == nil:
				wins++
				returned[ref.ID] = ref.Amount.Minor
				expectedSum += ref.Amount.Minor
			case errors.Is(err, payment.ErrVersionConflict):
				conflicts++
			default:
				t.Errorf("unexpected error: %v", err)
			}
		}(amt)
	}
	ready.Wait()
	repo.onGet = nil
	close(release)
	done.Wait()

	if wins != 1 || conflicts != workers-1 {
		t.Fatalf("wins=%d conflicts=%d, want 1 and %d", wins, conflicts, workers-1)
	}

	got, err := svc.Get(ctx, p.ID)
	if err != nil {
		t.Fatal(err)
	}
	if len(got.Refunds) != 4 || got.Refunded != expectedSum {
		t.Fatalf("got len(Refunds)=%d Refunded=%d, want 4 and %d", len(got.Refunds), got.Refunded, expectedSum)
	}
	var sum int64
	for _, r := range got.Refunds {
		want, ok := returned[r.ID]
		if !ok || r.Amount.Minor != want {
			t.Fatalf("unexpected/corrupted refund entry %+v (returned=%v)", r, returned)
		}
		sum += r.Amount.Minor
	}
	if sum != got.Refunded {
		t.Fatalf("sum(Refunds)=%d != Refunded=%d", sum, got.Refunded)
	}
}

