  1	package payment
  2	
  3	import (
  4		"context"
  5		"fmt"
  6		"sync"
  7	
  8		"example.com/gopayments/clock"
  9		"example.com/gopayments/money"
 10	)
 11	
 12	// IDGenerator creates unique identifiers with a type prefix.
 13	type IDGenerator interface {
 14		NewID(prefix string) string
 15	}
 16	
 17	// SeqIDs is a deterministic IDGenerator ("pay_000001", "ref_000002", ...).
 18	type SeqIDs struct {
 19		mu sync.Mutex
 20		n  int
 21	}
 22	
 23	// NewSeqIDs returns a sequential generator starting at 1.
 24	func NewSeqIDs() *SeqIDs { return &SeqIDs{} }
 25	
 26	// NewID returns the next identifier.
 27	func (g *SeqIDs) NewID(prefix string) string {
 28		g.mu.Lock()
 29		defer g.mu.Unlock()
 30		g.n++
 31		return fmt.Sprintf("%s_%06d", prefix, g.n)
 32	}
 33	
 34	// Config tunes the service.
 35	type Config struct {
 36		// FeeBps is the processing fee in basis points charged on every payment.
 37		FeeBps int64
 38	}
 39	
 40	// Service drives the payment lifecycle.
 41	type Service struct {
 42		repo   Repository
 43		clock  clock.Clock
 44		ids    IDGenerator
 45		events Publisher
 46		cfg    Config
 47	}
 48	
 49	// NewService wires a Service. events may be nil.
 50	func NewService(repo Repository, clk clock.Clock, ids IDGenerator, events Publisher, cfg Config) *Service {
 51		return &Service{repo: repo, clock: clk, ids: ids, events: events, cfg: cfg}
 52	}
 53	
 54	// CreateInput is the input of Create.
 55	type CreateInput struct {
 56		MerchantID string
 57		Amount     money.Amount
 58	}
 59	
 60	// Create registers a new payment in status CREATED.
 61	func (s *Service) Create(ctx context.Context, in CreateInput) (Payment, error) {
 62		if in.MerchantID == "" {
 63			return Payment{}, fmt.Errorf("%w: merchant id is required", ErrInvalidInput)
 64		}
 65		if !in.Amount.IsPositive() {
 66			return Payment{}, fmt.Errorf("%w: amount must be positive, got %s", ErrInvalidInput, in.Amount)
 67		}
 68		fee, err := money.Fee(in.Amount, s.cfg.FeeBps)
 69		if err != nil {
 70			return Payment{}, fmt.Errorf("compute fee: %w", err)
 71		}
 72		now := s.clock.Now()
 73		p := Payment{
 74			ID:         s.ids.NewID("pay"),
 75			MerchantID: in.MerchantID,
 76			Amount:     in.Amount,
 77			Fee:        fee,
 78			Status:     StatusCreated,
 79			Version:    1,
 80			CreatedAt:  now,
 81			UpdatedAt:  now,
 82		}
 83		if err := s.repo.Create(ctx, p.Clone()); err != nil {
 84			return Payment{}, fmt.Errorf("create payment: %w", err)
 85		}
 86		s.publish(ctx, Event{Type: "payment.created", Payment: p.Clone()})
 87		return p, nil
 88	}
 89	
 90	// Get loads a payment.
 91	func (s *Service) Get(ctx context.Context, id string) (Payment, error) {
 92		p, err := s.repo.Get(ctx, id)
 93		if err != nil {
 94			return Payment{}, fmt.Errorf("get payment %s: %w", id, err)
 95		}
 96		return p.Clone(), nil
 97	}
 98	
 99	// List returns one page of a merchant's payments.
100	func (s *Service) List(ctx context.Context, merchantID string, page Page) ([]Payment, string, error) {
101		if merchantID == "" {
102			return nil, "", fmt.Errorf("%w: merchant id is required", ErrInvalidInput)
103		}
104		ps, next, err := s.repo.ListByMerchant(ctx, merchantID, page)
105		if err != nil {
106			return nil, "", fmt.Errorf("list payments of %s: %w", merchantID, err)
107		}
108		for i := range ps {
109			ps[i] = ps[i].Clone()
110		}
111		return ps, next, nil
112	}
113	
114	// Authorize moves a CREATED payment to PENDING (sent to the provider).
115	func (s *Service) Authorize(ctx context.Context, id string) (Payment, error) {
116		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
117			switch p.Status {
118			case StatusCreated:
119				p.Status = StatusPending
120				return Event{Type: "payment.pending"}, nil
121			default:
122				return Event{}, fmt.Errorf("%w: cannot authorize a %s payment", ErrInvalidTransition, p.Status)
123			}
124		})
125	}
126	
127	// Capture moves a PENDING payment to SUCCEEDED.
128	func (s *Service) Capture(ctx context.Context, id string) (Payment, error) {
129		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
130			switch p.Status {
131			case StatusPending:
132				p.Status = StatusSucceeded
133				return Event{Type: "payment.succeeded"}, nil
134			default:
135				return Event{}, fmt.Errorf("%w: cannot capture a %s payment", ErrInvalidTransition, p.Status)
136			}
137		})
138	}
139	
140	// Decline moves a CREATED or PENDING payment to DECLINED.
141	func (s *Service) Decline(ctx context.Context, id, reason string) (Payment, error) {
142		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
143			switch p.Status {
144			case StatusCreated, StatusPending:
145				p.Status = StatusDeclined
146				p.DeclineReason = reason
147				return Event{Type: "payment.declined"}, nil
148			default:
149				return Event{}, fmt.Errorf("%w: cannot decline a %s payment", ErrInvalidTransition, p.Status)
150			}
151		})
152	}
153	
154	// Refund refunds amount of a SUCCEEDED payment. Partial refunds keep the
155	// payment SUCCEEDED; once the whole amount is refunded it becomes REFUNDED.
156	func (s *Service) Refund(ctx context.Context, id string, amount money.Amount) (Payment, Refund, error) {
157		if !amount.IsPositive() {
158			return Payment{}, Refund{}, fmt.Errorf("%w: refund amount must be positive, got %s", ErrInvalidInput, amount)
159		}
160		var refund Refund
161		p, err := s.mutate(ctx, id, func(p *Payment) (Event, error) {
162			switch p.Status {
163			case StatusSucceeded:
164			default:
165				return Event{}, fmt.Errorf("%w: cannot refund a %s payment", ErrInvalidTransition, p.Status)
166			}
167			if amount.Currency != p.Amount.Currency {
168				return Event{}, fmt.Errorf("%w: refund in %s for a %s payment", money.ErrCurrencyMismatch, amount.Currency.Code, p.Amount.Currency.Code)
169			}
170			if amount.Minor > p.Remaining().Minor {
171				return Event{}, fmt.Errorf("%w: requested %s, remaining %s", ErrRefundExceedsRemaining, amount, p.Remaining())
172			}
173			refund = Refund{ID: s.ids.NewID("ref"), Amount: amount, CreatedAt: s.clock.Now()}
174			p.Refunded += amount.Minor
175			p.Refunds = append(p.Refunds, refund)
176			evType := "payment.partially_refunded"
177			if p.Refunded == p.Amount.Minor {
178				p.Status = StatusRefunded
179				evType = "payment.refunded"
180			}
181			evRefund := refund
182			return Event{Type: evType, Refund: &evRefund}, nil
183		})
184		if err != nil {
185			return Payment{}, Refund{}, err
186		}
187		return p, refund, nil
188	}
189	
190	// mutate loads a payment, applies change and saves it with optimistic locking.
191	func (s *Service) mutate(ctx context.Context, id string, change func(p *Payment) (Event, error)) (Payment, error) {
192		p, err := s.repo.Get(ctx, id)
193		if err != nil {
194			return Payment{}, fmt.Errorf("load payment %s: %w", id, err)
195		}
196		p = p.Clone()
197		ev, err := change(&p)
198		if err != nil {
199			return Payment{}, fmt.Errorf("payment %s: %w", id, err)
200		}
201		p.UpdatedAt = s.clock.Now()
202		if err := s.repo.Update(ctx, p.Clone()); err != nil {
203			return Payment{}, fmt.Errorf("save payment %s: %w", id, err)
204		}
205		p.Version++
206		ev.Payment = p.Clone()
207		s.publish(ctx, ev)
208		return p, nil
209	}
210	
211	func (s *Service) publish(ctx context.Context, ev Event) {
212		if s.events == nil {
213			return
214		}
215		// Delivery is asynchronous and retried by the dispatcher; a failure to
216		// enqueue must not fail the payment operation.
217		_ = s.events.Publish(ctx, ev)
218	}

  1	// Package store provides repository implementations for the payment domain.
  2	package store
  3	
  4	import (
  5		"context"
  6		"encoding/base64"
  7		"fmt"
  8		"strconv"
  9		"strings"
 10		"sync"
 11	
 12		"example.com/gopayments/payment"
 13	)
 14	
 15	const (
 16		defaultLimit = 20
 17		maxLimit     = 100
 18	)
 19	
 20	// Memory is an in-memory payment.Repository used in tests and local runs.
 21	type Memory struct {
 22		mu         sync.RWMutex
 23		byID       map[string]payment.Payment
 24		byMerchant map[string][]string // payment ids in creation order
 25	}
 26	
 27	var _ payment.Repository = (*Memory)(nil)
 28	
 29	// NewMemory returns an empty repository.
 30	func NewMemory() *Memory {
 31		return &Memory{
 32			byID:       make(map[string]payment.Payment),
 33			byMerchant: make(map[string][]string),
 34		}
 35	}
 36	
 37	// Create stores a new payment.
 38	func (m *Memory) Create(_ context.Context, p payment.Payment) error {
 39		m.mu.Lock()
 40		defer m.mu.Unlock()
 41		if _, ok := m.byID[p.ID]; ok {
 42			return fmt.Errorf("%w: %s", payment.ErrDuplicate, p.ID)
 43		}
 44		m.byID[p.ID] = p.Clone()
 45		m.byMerchant[p.MerchantID] = append(m.byMerchant[p.MerchantID], p.ID)
 46		return nil
 47	}
 48	
 49	// Get returns a deep copy of the stored payment.
 50	func (m *Memory) Get(_ context.Context, id string) (payment.Payment, error) {
 51		m.mu.RLock()
 52		defer m.mu.RUnlock()
 53		p, ok := m.byID[id]
 54		if !ok {
 55			return payment.Payment{}, fmt.Errorf("%w: %s", payment.ErrNotFound, id)
 56		}
 57		return p.Clone(), nil
 58	}
 59	
 60	// Update replaces the stored payment if versions match.
 61	func (m *Memory) Update(_ context.Context, p payment.Payment) error {
 62		m.mu.Lock()
 63		defer m.mu.Unlock()
 64		cur, ok := m.byID[p.ID]
 65		if !ok {
 66			return fmt.Errorf("%w: %s", payment.ErrNotFound, p.ID)
 67		}
 68		if cur.Version != p.Version {
 69			return fmt.Errorf("%w: payment %s has version %d, update based on %d", payment.ErrVersionConflict, p.ID, cur.Version, p.Version)
 70		}
 71		next := p.Clone()
 72		next.Version++
 73		m.byID[p.ID] = next
 74		return nil
 75	}
 76	
 77	// ListByMerchant pages through a merchant's payments in creation order.
 78	func (m *Memory) ListByMerchant(_ context.Context, merchantID string, page payment.Page) ([]payment.Payment, string, error) {
 79		limit := page.Limit
 80		switch {
 81		case limit < 0:
 82			return nil, "", fmt.Errorf("%w: limit must not be negative", payment.ErrInvalidInput)
 83		case limit == 0:
 84			limit = defaultLimit
 85		case limit > maxLimit:
 86			limit = maxLimit
 87		}
 88		offset := 0
 89		if page.Cursor != "" {
 90			var err error
 91			if offset, err = decodeCursor(page.Cursor); err != nil {
 92				return nil, "", err
 93			}
 94		}
 95	
 96		m.mu.RLock()
 97		defer m.mu.RUnlock()
 98		ids := m.byMerchant[merchantID]
 99		if offset > len(ids) {
100			offset = len(ids)
101		}
102		end := min(offset+limit, len(ids))
103		out := make([]payment.Payment, 0, end-offset)
104		for _, id := range ids[offset:end] {
105			out = append(out, m.byID[id].Clone())
106		}
107		next := ""
108		if end < len(ids) {
109			next = encodeCursor(end)
110		}
111		return out, next, nil
112	}
113	
114	func encodeCursor(offset int) string {
115		return base64.RawURLEncoding.EncodeToString([]byte("o:" + strconv.Itoa(offset)))
116	}
117	
118	func decodeCursor(c string) (int, error) {
119		raw, err := base64.RawURLEncoding.DecodeString(c)
120		if err != nil {
121			return 0, fmt.Errorf("%w: %v", payment.ErrInvalidCursor, err)
122		}
123		n, ok := strings.CutPrefix(string(raw), "o:")
124		if !ok {
125			return 0, fmt.Errorf("%w: unexpected format", payment.ErrInvalidCursor)
126		}
127		off, err := strconv.Atoi(n)
128		if err != nil || off < 0 {
129			return 0, fmt.Errorf("%w: bad offset %q", payment.ErrInvalidCursor, n)
130		}
131		return off, nil
132	}
